import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

interface IBreakpointOrganizer {
    String getLabel();
}

public class MyClass {
    List<Object> fSorted = new ArrayList<>();

    void sortOrganizers() {
        fSorted.add(new IBreakpointOrganizer() { public String getLabel() { return "C"; }});
        fSorted.add(new IBreakpointOrganizer() { public String getLabel() { return "A"; }});
        Collections.sort(fSorted, new Comparator<Object>() {
            @Override
            public int compare(Object o1, Object o2) {
                IBreakpointOrganizer b1 = (IBreakpointOrganizer)o1;
                IBreakpointOrganizer b2 = (IBreakpointOrganizer)o2;
                return b1.getLabel().compareTo(b2.getLabel());
            }
        });
    }
}

